  const elapsedMs = Number(process.hrtime.bigint() - start) / 1e6;
  assert.equal(result.status, 0);
  assert.ok(
    elapsedMs < 200,
    `no-op path should be fast (<200ms), took ${elapsedMs.toFixed(1)}ms`,
  );
});

